import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Crimson Project Update - Matan Breizman & Aishwarya Mathuria, IBM","description":"","frontmatter":{"title":"Crimson Project Update - Matan Breizman & Aishwarya Mathuria, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Crimson Project","Distributed Storage","Performance Optimization","Storage Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Crimson_Project_Update_-_Matan_Breizman_Aishwarya_Mathuria_IBM.md","filePath":"posts/2025/Crimson_Project_Update_-_Matan_Breizman_Aishwarya_Mathuria_IBM.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Crimson_Project_Update_-_Matan_Breizman_Aishwarya_Mathuria_IBM.md"};function s(e,r,l,g,h,_){return o(),a("div",null,[...r[0]||(r[0]=[i('<h3 id="会议纪要-ceph-crimson项目进展与未来规划" tabindex="-1">会议纪要：Ceph Crimson项目进展与未来规划 <a class="header-anchor" href="#会议纪要-ceph-crimson项目进展与未来规划" aria-label="Permalink to &quot;会议纪要：Ceph Crimson项目进展与未来规划&quot;">​</a></h3><p><strong>会议时间</strong>：未知<br><strong>主讲人</strong>：Matan Breizman, Ashwarya Mathuria, IBM</p><h4 id="_1-会议背景与主题" tabindex="-1">1. <strong>会议背景与主题</strong> <a class="header-anchor" href="#_1-会议背景与主题" aria-label="Permalink to &quot;1. **会议背景与主题**&quot;">​</a></h4><ul><li><strong>主题</strong>：Ceph Crimson项目的最新进展与未来规划。</li><li><strong>目标</strong>：介绍Crimson项目的背景、设计理念、性能优化以及未来发展方向。</li></ul><h4 id="_2-crimson项目背景" tabindex="-1">2. <strong>Crimson项目背景</strong> <a class="header-anchor" href="#_2-crimson项目背景" aria-label="Permalink to &quot;2. **Crimson项目背景**&quot;">​</a></h4><ul><li><strong>硬件发展</strong>：现代硬件（如NVMe、ZNS等）的IO速度和CPU核心数量提升，传统Ceph OSD架构在高性能硬件上表现不佳。</li><li><strong>问题</strong>：传统Ceph OSD架构依赖多线程模型，导致CPU上下文切换频繁，性能瓶颈明显。</li><li><strong>目标</strong>：通过Crimson项目，重写Ceph OSD，减少CPU开销，提升性能，充分利用现代硬件。</li></ul><h4 id="_3-crimson项目设计理念" tabindex="-1">3. <strong>Crimson项目设计理念</strong> <a class="header-anchor" href="#_3-crimson项目设计理念" aria-label="Permalink to &quot;3. **Crimson项目设计理念**&quot;">​</a></h4><ul><li><strong>共享无架构（Shared Nothing Architecture）</strong>：每个核心独立处理任务，避免跨核心通信和锁竞争。</li><li><strong>异步框架</strong>：使用Seastar框架，实现单线程单核心的高效IO路径处理。</li><li><strong>任务切换</strong>：使用用户空间任务切换，减少操作系统上下文切换的开销。</li></ul><h4 id="_4-crimson与传统osd的对比" tabindex="-1">4. <strong>Crimson与传统OSD的对比</strong> <a class="header-anchor" href="#_4-crimson与传统osd的对比" aria-label="Permalink to &quot;4. **Crimson与传统OSD的对比**&quot;">​</a></h4><ul><li><strong>传统OSD</strong>：多线程模型，依赖锁和上下文切换，性能受限于线程间协调。</li><li><strong>Crimson OSD</strong>：单线程单核心处理，减少锁和上下文切换，提升性能。</li><li><strong>性能测试</strong>：Crimson在随机读取4K块大小的RBD工作负载下，显著减少了上下文切换和CPU迁移，性能提升40%-50%。</li></ul><h4 id="_5-pg-splitting的实现对比" tabindex="-1">5. <strong>PG Splitting的实现对比</strong> <a class="header-anchor" href="#_5-pg-splitting的实现对比" aria-label="Permalink to &quot;5. **PG Splitting的实现对比**&quot;">​</a></h4><ul><li><strong>传统OSD</strong>：PG Splitting需要获取锁，且一次只能处理一个PG，效率较低。</li><li><strong>Crimson OSD</strong>：每个核心独立处理PG Splitting，无需锁，支持并行处理多个PG。</li></ul><h4 id="_6-性能数据" tabindex="-1">6. <strong>性能数据</strong> <a class="header-anchor" href="#_6-性能数据" aria-label="Permalink to &quot;6. **性能数据**&quot;">​</a></h4><ul><li><strong>上下文切换</strong>：Crimson减少了99%的上下文切换，避免了CPU迁移。</li><li><strong>网络层性能</strong>：Crimson的Messenger组件在多核心环境下表现出更好的扩展性。</li><li><strong>整体性能</strong>：Crimson在3个OSD、每个OSD 10核心的配置下，性能比传统OSD提升40%-50%。</li></ul><h4 id="_7-当前可用性" tabindex="-1">7. <strong>当前可用性</strong> <a class="header-anchor" href="#_7-当前可用性" aria-label="Permalink to &quot;7. **当前可用性**&quot;">​</a></h4><ul><li><strong>部署状态</strong>：Crimson目前处于技术预览阶段，支持RBD和复制池的基本功能，但不建议在生产环境中使用。</li><li><strong>实验性标志</strong>：为防止误用，Crimson启动时需要显式启用实验性标志。</li></ul><h4 id="_8-未来工作" tabindex="-1">8. <strong>未来工作</strong> <a class="header-anchor" href="#_8-未来工作" aria-label="Permalink to &quot;8. **未来工作**&quot;">​</a></h4><ul><li><strong>支持更多功能</strong>：未来将支持纠删码池、自动扩展PG、RGW、QoS、mClock调度器等。</li><li><strong>后端替换</strong>：计划在T版本中将BlueStore替换为CStore，进一步提升性能。</li></ul><h4 id="_9-cstore介绍" tabindex="-1">9. <strong>CStore介绍</strong> <a class="header-anchor" href="#_9-cstore介绍" aria-label="Permalink to &quot;9. **CStore介绍**&quot;">​</a></h4><ul><li><strong>目标</strong>：CStore是Crimson的专用后端，旨在更好地支持现代存储设备（如ZNS）。</li><li><strong>架构</strong>：基于Seastar框架，设计为共享无架构，元数据存储使用BitRI，避免依赖RocksDB。</li><li><strong>当前状态</strong>：CStore已稳定，支持Rados API，正在进行性能优化和功能扩展。</li></ul><h4 id="_10-问答环节" tabindex="-1">10. <strong>问答环节</strong> <a class="header-anchor" href="#_10-问答环节" aria-label="Permalink to &quot;10. **问答环节**&quot;">​</a></h4><ul><li><strong>核心数量与性能</strong>：Crimson在更多核心的硬件上表现更好，但核心频率较低的硬件可能表现不如预期。</li><li><strong>PG数量建议</strong>：Crimson的PG数量建议可能与传统OSD不同，未来将提供更具体的建议。</li><li><strong>CStore支持的设备</strong>：CStore将支持多种存储设备，包括HDD和SSD，未来还将支持ZNS等新兴技术。</li></ul><h4 id="_11-总结" tabindex="-1">11. <strong>总结</strong> <a class="header-anchor" href="#_11-总结" aria-label="Permalink to &quot;11. **总结**&quot;">​</a></h4><ul><li>Crimson项目是Ceph下一代OSD的重写，旨在充分利用现代硬件，提升性能和可扩展性。</li><li>目前Crimson已支持RBD和复制池的基本功能，未来将逐步支持更多功能和优化后端性能。</li></ul><p><strong>后续行动计划</strong>：</p><ol><li><strong>性能评估</strong>：继续进行性能测试，特别是在多主机和复杂环境下的表现。</li><li><strong>功能扩展</strong>：支持纠删码池、RGW、QoS等功能。</li><li><strong>后端替换</strong>：在T版本中将BlueStore替换为CStore，进一步提升性能。</li><li><strong>用户反馈</strong>：鼓励用户测试Crimson，并提供反馈以改进项目。</li></ol><p><strong>会议结束</strong>：感谢与会者的参与和提问，会议圆满结束。</p>',27)])])}const u=t(n,[["render",s]]);export{d as __pageData,u as default};
